CREATE TABLE IF NOT EXISTS `rubric_criteria` (`id` INT AUTO_INCREMENT PRIMARY KEY, `slug` VARCHAR(24) NOT NULL UNIQUE, `name` VARCHAR(64) NOT NULL, `description` VARCHAR(255) NOT NULL DEFAULT '', `weight` INT NOT NULL DEFAULT 20) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO `rubric_criteria` (`slug`, `name`, `description`, `weight`) VALUES ('konsep', 'Konsep & brief', 'Karya menjawab brief dan punya ide jelas', 25), ('tipografi', 'Tipografi', 'Pilihan dan susunan huruf rapi terbaca', 20), ('warna', 'Warna', 'Palet konsisten dan mendukung pesan', 20), ('layout', 'Layout', 'Komposisi, hierarki, dan ruang seimbang', 20), ('presentasi', 'Presentasi', 'Kerapian file dan cara mempresentasikan', 15);
CREATE TABLE IF NOT EXISTS `submission_scores` (`id` INT AUTO_INCREMENT PRIMARY KEY, `owner_id` INT NOT NULL, `quest_id` INT NOT NULL, `criterion_id` INT NOT NULL, `score` TINYINT NOT NULL DEFAULT 3, `note` VARCHAR(300) NULL, `rater_id` INT NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT `uq_sub_score` UNIQUE (`owner_id`, `quest_id`, `criterion_id`, `rater_id`), CONSTRAINT `fk_sub_score_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_sub_score_quest` FOREIGN KEY (`quest_id`) REFERENCES `quests` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_sub_score_rater` FOREIGN KEY (`rater_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
